import { Component, createSignal, Show } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { TextInput, TextInputProps } from "#core/ui-next/components/text-input.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

const SearchBarComponent: Component<TextInputProps> = (props) => {
	const [isEditing, setIsEditing] = createSignal<boolean>(false);

	return (
		<TextInput
			{...props}
			setIsEditing={setIsEditing}
			disableFocus={props.disableFocus ?? true}
		>
			<Show when={!isEditing() && !props.value()}>
				<div class="absolute inset-0 flex flex-row items-center justify-start pointer-events-none">
					<div class="m-2 text-accent-2">
						<L10n.Compose text="LOC_OPTIONS_SEARCH" />
					</div>
				</div>

				<Icon
					class="absolute right-1 top-1 size-8 pointer-events-none"
					name="url('blp:soc_search')"
				/>
			</Show>
		</TextInput>
	);
};

export const SearchBar = ComponentRegistry.register("Search", SearchBarComponent);
